head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.gAcptNo;
scwin.gViewerStat = "R"; // 처리시 뷰=P,  조회시 뷰=R
scwin.gIsurCd;
scwin.vScrenID = 'ULDSTF15800.xml';
scwin.search_yn = false;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    // 현재날짜 셋팅	
    edt_SrchDay.setValue($c.ut.cGetToday("yyyymmdd"));

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !담당자--;
검토대상;
클릭-- > function() {
    /*
    alert("js_bond_yn-->"+js_bond_yn);
    alert("gLdMktTp-->"+gLdMktTp);
    */
    if ($c.stf.getObjectValue(edt_SrchDay).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_SrchDay.focus();
        return;
    }
    $c.cm.ShowWin_yn(grd_Grid, scwin.search_yn);
    var url = "/DisclosureSearch.do?method=listBndMktActNotiSrch&inputMessageId=DSCLDETAILLIST_OUT" + "&outputMessageId=DSCLDETAILLIST_OUT" + "&PUBL_DDTM=" + $c.stf.getObjectValue(edt_SrchDay) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_List.DataID = encodeURI(url);
    dts_List.reset();

    //ShowWin(grd_Grid);

};




// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    scwin.gAcptNo = dts_List.getCellData(eval(obj), "ACPT_NO");
    scwin.gIsurCd = dts_List.getCellData(eval(obj), "ISUR_CD");
};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.fn_setContnId(row);
    if (colid == "DOC_TITLE") {
        //2017-11-29 KBoY 비공개 첨부서류 볼 수 없음.
        $c.stf.fn_OpenDisclViewer(scwin.gAcptNo, scwin.gViewerStat, scwin.vScrenID);
    } else if (colid == "ACPT_DDTM") {
        $c.stf.fn_OpenDisclAllList();
    } else if (colid == "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    }
};
scwin.btn_Search_onclick = function() {
    scwin.search_yn = true;
    fn_Search();
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
    //CloseWin('', grd_Grid); 

    scwin.search_yn = false;
    $c.cm.CloseWin(0, grd_Grid);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    }

    //CloseWin(rowcount, grd_Grid);	//조회완료시 LOADING 이미지 종료

    scwin.search_yn = false;
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_Grid, "채권시장조치알람 목록", "", "2");
};
scwin.img_Cal_onclick = function() {
    popUpCalendar2(edt_SrchDay);
};
scwin.gform_onload = function() {
    // 리로드 시 스크립트 오류로 인해 패치함

    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();
    fn_Search();
};
